const msg = $input.first().json.message;
const caption = msg.caption || '';
const chatId = msg.chat.id;

const pqMatch = caption.match(/^PQ:\s*(.+)/i);
const fullLabel = pqMatch ? pqMatch[1].trim() : 'Unknown Course';

const yearMatch = fullLabel.match(/(\d{4})/);
const year = yearMatch ? yearMatch[1] : 'Unknown Year';
const courseName = fullLabel.replace(/\d{4}/, '').trim();

let fileId, fileType;
if (msg.photo) {
  const photos = msg.photo;
  fileId = photos[photos.length - 1].file_id;
  fileType = 'image';
} else if (msg.document) {
  fileId = msg.document.file_id;
  fileType = msg.document.mime_type === 'application/pdf' ? 'pdf' : 'image';
}

return [{
  json: {
    chat_id: chatId,
    course_name: courseName,
    year: year,
    full_label: fullLabel,
    file_id: fileId,
    file_type: fileType
  }
}];

