const filePath = $input.first().json.result.file_path;
const prev = $('Extract Caption and File Info').first().json;
const credentials = await this.getCredentials('telegramApi');
const token = credentials.accessToken;

return [{
  json: {
    ...prev,
    download_url: `https://api.telegram.org/file/bot${token}/${filePath}`
  }
}];

const item = $input.first();
const prev = $('Build Download URL').first().json;
const binary = item.binary?.pqFile;

if (!binary) throw new Error('File download failed — no binary data.');

const base64 = binary.data;
const mimeType = binary.mimeType || 'image/jpeg';
const fileType = prev.file_type;

let contentBlock;
if (fileType === 'pdf') {
  contentBlock = {
    type: 'document',
    source: { type: 'base64', media_type: 'application/pdf', data: base64 }
  };
} else {
  const imgMime = mimeType.startsWith('image/') ? mimeType : 'image/jpeg';
  contentBlock = {
    type: 'image',
    source: { type: 'base64', media_type: imgMime, data: base64 }
  };
}

return [{
  json: {
    ...prev,
    content_block: contentBlock
  }
}];

const prev = $input.first().json;
const course = prev.course_name;
const year = prev.year;
const contentBlock = prev.content_block;

const sysLines = [
  'You are an exam preparation assistant for a Nigerian federal university computer engineering student. You will receive an image or PDF of a past exam question paper.',
  '',
  'Your job is to return a single JSON object and nothing else — no markdown, no explanation, no code fences, just raw JSON.',
  '',
  'The JSON must have this exact structure:',
  '{',
  '  "course": "course name as you can determine it",',
  '  "pattern_analysis": "A paragraph analysing which topics appear most frequently, which question types dominate (calculation vs theory vs diagram), and which 3-5 topics the student should prioritise based on this paper alone.",',
  '  "priority_topics": ["topic1", "topic2", "topic3"],',
  '  "total_questions": 10,',
  '  "questions": [',
  '    {',
  '      "number": 1,',
  '      "question_text": "Full question text exactly as it appears",',
  '      "topic": "topic this question covers",',
  '      "marks": "marks allocated if visible, else null",',
  '      "question_type": "calculation OR theory OR diagram OR definition",',
  '      "model_answer": "A complete model answer that would score full marks in this exam. Be thorough. Show all working for calculations. Give full explanations for theory. This answer must be good enough to copy into an answer booklet and receive full marks.",',
  '      "key_points": ["key point 1", "key point 2", "key point 3"],',
  '      "time_to_answer_minutes": 5',
  '    }',
  '  ]',
  '}'
];
const systemPrompt = sysLines.join('\n');

const requestBody = JSON.stringify({
  model: 'claude-sonnet-4-20250514',
  max_tokens: 8000,
  system: systemPrompt,
  messages: [{
    role: 'user',
    content: [
      contentBlock,
      {
        type: 'text',
        text: 'This is a past exam question paper for ' + course + ' (' + year + '). Extract every question and generate complete model answers. Return only the JSON.'
      }
    ]
  }]
});

return [{ json: { ...prev, request_body: requestBody } }];

const response = $input.first().json;
const rawText = (response.content || [])[0]?.text || '';
const prev = $('Prepare File for Claude').first().json;

let pqData;
try {
  const cleaned = rawText
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```\s*$/i, '')
    .trim();
  pqData = JSON.parse(cleaned);
} catch(e) {
  throw new Error('Claude did not return valid JSON: ' + rawText.slice(0, 300));
}

const totalQ = pqData.questions.length;
const estimatedTotal = pqData.questions.reduce(
  (sum, q) => sum + (q.time_to_answer_minutes || 5), 0
);

let summaryMsg = '\u2705 *Past Questions Processed!*\n';
summaryMsg += '\uD83D\uDCDA ' + pqData.course + ' \u2014 ' + prev.year + '\n';
summaryMsg += '\uD83D\uDCDD ' + totalQ + ' questions found\n';
summaryMsg += '\u23F1 Estimated exam time: ' + estimatedTotal + ' mins\n\n';
summaryMsg += '\uD83C\uDFAF *PATTERN ANALYSIS*\n';
summaryMsg += pqData.pattern_analysis + '\n\n';
summaryMsg += '\uD83D\uDD25 *PRIORITY TOPICS*\n';
pqData.priority_topics.forEach((t, i) => {
  summaryMsg += (i + 1) + '. ' + t + '\n';
});
summaryMsg += '\n\uD83D\uDCCB *ALL QUESTIONS:*\n';
pqData.questions.forEach(q => {
  const marks = q.marks ? ' [' + q.marks + ' marks]' : '';
  summaryMsg += 'Q' + q.number + '. ' + q.question_text.slice(0, 80) + '...' + marks + '\n';
});
summaryMsg += '\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n';
summaryMsg += 'Reply *ANSWER: N* to get the full model answer for question N\n';
summaryMsg += 'Reply *SIMULATE* to run a timed exam simulation';

let driveContent = '# ' + pqData.course + ' \u2014 Past Questions ' + prev.year + '\n\n';
driveContent += '## Pattern Analysis\n' + pqData.pattern_analysis + '\n\n';
driveContent += '## Priority Topics\n';
pqData.priority_topics.forEach((t, i) => { driveContent += (i + 1) + '. ' + t + '\n'; });
driveContent += '\n---\n\n';
pqData.questions.forEach(q => {
  driveContent += '## Q' + q.number + '. ' + q.question_text + '\n\n';
  driveContent += '**Topic:** ' + q.topic + ' | **Type:** ' + q.question_type;
  if (q.marks) driveContent += ' | **Marks:** ' + q.marks;
  driveContent += '\n\n### Model Answer\n' + q.model_answer + '\n\n';
  driveContent += '### Key Points\n';
  q.key_points.forEach(kp => { driveContent += '- ' + kp + '\n'; });
  driveContent += '\n---\n\n';
});

const staticData = $getWorkflowStaticData('global');
staticData['pq_' + prev.chat_id] = JSON.stringify(pqData);
staticData['pq_course_' + prev.chat_id] = pqData.course;
staticData['pq_year_' + prev.chat_id] = prev.year;

return [{
  json: {
    chat_id: prev.chat_id,
    course_name: pqData.course,
    year: prev.year,
    summary_message: summaryMsg,
    drive_content: driveContent,
    total_questions: totalQ,
    pq_data: JSON.stringify(pqData)
  }
}];

const text = $input.first().json.message.text;
const chatId = $input.first().json.message.chat.id;

const match = text.match(/ANSWER:\s*(\d+)/i);
if (!match) {
  return [{
    json: {
      chat_id: chatId,
      error: true,
      error_msg: 'Please specify a question number. Example: ANSWER: 3'
    }
  }];
}

const questionNumber = parseInt(match[1]);

const staticData = $getWorkflowStaticData('global');
const pqRaw = staticData['pq_' + chatId];

if (!pqRaw) {
  return [{
    json: {
      chat_id: chatId,
      error: true,
      error_msg: 'No past questions loaded yet. Please send a past question paper first with the caption: PQ: [Course Name]'
    }
  }];
}

const pqData = JSON.parse(pqRaw);
const question = pqData.questions.find(q => q.number === questionNumber);

if (!question) {
  return [{
    json: {
      chat_id: chatId,
      error: true,
      error_msg: 'Question ' + questionNumber + ' not found. This paper has ' + pqData.questions.length + ' questions.'
    }
  }];
}

let answerMsg = '\uD83D\uDCCC *Q' + question.number + ': ' + question.question_text + '*\n\n';
answerMsg += '\uD83C\uDFF7 Topic: ' + question.topic + '\n';
if (question.marks) answerMsg += '\u2B50 Marks: ' + question.marks + '\n';
answerMsg += '\u23F1 Est. time: ' + question.time_to_answer_minutes + ' mins\n\n';
answerMsg += '\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\n';
answerMsg += '\u2705 *MODEL ANSWER:*\n\n' + question.model_answer + '\n\n';
answerMsg += '\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\n';
answerMsg += '\uD83D\uDD11 *Key Points to Hit:*\n';
question.key_points.forEach(kp => { answerMsg += '\u2022 ' + kp + '\n'; });

return [{
  json: {
    chat_id: chatId,
    error: false,
    answer_message: answerMsg,
    total_questions: pqData.questions.length,
    question_number: questionNumber
  }
}];

const answerText = $input.first().json.answer_message;
const chatId = $input.first().json.chat_id;
const chunkSize = 4000;
const chunks = [];
for (let i = 0; i < answerText.length; i += chunkSize) {
  chunks.push(answerText.slice(i, i + chunkSize));
}
return chunks.map((chunk, i) => ({
  json: { text: chunk, chat_id: chatId, chunk_index: i }
}));

const chatId = $input.first().json.message.chat.id;
const staticData = $getWorkflowStaticData('global');
const pqRaw = staticData['pq_' + chatId];

if (!pqRaw) {
  return [{
    json: {
      chat_id: chatId,
      error: true,
      error_msg: 'No past questions loaded. Send a past question paper first: PQ: [Course Name]'
    }
  }];
}

const pqData = JSON.parse(pqRaw);
const totalTime = pqData.questions.reduce(
  (s, q) => s + (q.time_to_answer_minutes || 5), 0
);

let simMsg = '\u23F1 *EXAM SIMULATION \u2014 ' + pqData.course + '*\n\n';
simMsg += 'Total questions: ' + pqData.questions.length + '\n';
simMsg += 'Estimated time: ' + totalTime + ' minutes\n\n';
simMsg += '\uD83D\uDEA8 *Rules:*\n';
simMsg += '\u2022 Answer on paper, not on your phone\n';
simMsg += '\u2022 Do not scroll up to check notes\n';
simMsg += '\u2022 Time yourself\n\n';
simMsg += '\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\n';

pqData.questions.forEach(q => {
  const marks = q.marks ? ' (' + q.marks + ' marks)' : '';
  simMsg += '*' + q.number + '.* ' + q.question_text + marks + '\n\n';
});

simMsg += '\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n';
simMsg += 'Start your timer NOW. \u23F1\n';
simMsg += 'When done, reply: *DONE*\n';
simMsg += '(I will send all model answers immediately)';

staticData['sim_active_' + chatId] = 'true';
staticData['sim_pq_' + chatId] = pqRaw;

return [{
  json: {
    chat_id: chatId,
    error: false,
    sim_message: simMsg,
    pq_data: pqRaw
  }
}];

const chatId = $input.first().json.message.chat.id;
const staticData = $getWorkflowStaticData('global');
const pqRaw = staticData['sim_pq_' + chatId] || staticData['pq_' + chatId];

if (!pqRaw) {
  return [{
    json: {
      chat_id: chatId,
      text: 'No active simulation found. Start with SIMULATE first.',
      chunk_index: 0,
      is_last: true
    }
  }];
}

const pqData = JSON.parse(pqRaw);

let allAnswers = '\u2705 *MODEL ANSWERS \u2014 ' + pqData.course + '*\n\n';
allAnswers += '\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\n';

pqData.questions.forEach(q => {
  allAnswers += '*Q' + q.number + '. ' + q.question_text + '*\n\n';
  allAnswers += '\uD83D\uDCCC ' + q.model_answer + '\n\n';
  allAnswers += '\uD83D\uDD11 *Key points:* ' + q.key_points.join(' | ') + '\n\n';
  allAnswers += '\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\n';
});

const chunkSize = 4000;
const chunks = [];
for (let i = 0; i < allAnswers.length; i += chunkSize) {
  chunks.push(allAnswers.slice(i, i + chunkSize));
}

return chunks.map((chunk, i) => ({
  json: {
    chat_id: chatId,
    text: chunk,
    chunk_index: i,
    is_last: i === chunks.length - 1
  }
}));
